from typing import List
class Solution:
    def minimumAddedCoins(self, coins: List[int], target: int) -> int:
        coins.sort()
        reach, added, i = 0, 0, 0
        while reach < target:
            if i < len(coins) and coins[i] <= reach + 1:
                reach += coins[i]; i += 1
            else:
                reach += reach + 1
                added += 1
        return added

c.cpp:
class Solution {
public:
    int minimumAddedCoins(vector<int>& coins, int target) {
        sort(coins.begin(), coins.end());
        long long reach = 0;
        int added = 0, i = 0;
        while (reach < target) {
            if (i < (int)coins.size() && coins[i] <= reach + 1) reach += coins[i++];
            else { reach += reach + 1; ++added; }
        }
        return added;
    }
};

